package com.shortplay.guard;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.widget.*;import android.view.*;
/** Guardian configuration is intentionally absent from the normal navigation. */
public class AdminActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(36,48,36,36);r.setBackgroundColor(Color.rgb(9,19,28));TextView h=new TextView(this);h.setText("Guardian configuration");h.setTextColor(Color.WHITE);h.setTextSize(28);r.addView(h);EditText email=new EditText(this);email.setHint("Guardian email");email.setInputType(33);r.addView(email);EditText endpoint=new EditText(this);endpoint.setHint("Secure email-service endpoint (HTTPS)");endpoint.setInputType(1);r.addView(endpoint);SharedPreferences p=getSharedPreferences("guard",MODE_PRIVATE);email.setText(p.getString("email",""));endpoint.setText(p.getString("endpoint",""));Button save=new Button(this);save.setText("Save");save.setOnClickListener(v->{p.edit().putString("email",email.getText().toString()).putString("endpoint",endpoint.getText().toString()).apply();Toast.makeText(this,"Guardian settings saved",Toast.LENGTH_SHORT).show();finish();});r.addView(save);TextView note=new TextView(this);note.setText("Use an HTTPS endpoint that sends a signed, one-time verification link. Email credentials must never be stored in this app.");note.setTextColor(Color.LTGRAY);r.addView(note);setContentView(r);}
}
